// Define valid ranges for each measurement, *after* final scaling. These use FINAL names.
const validRanges = {
    Temperature: { min: -1, max: 110 },
    pH:          { min: -0.5, max: 14.5 },
    ORP:         { min: -2100, max: 2100 },
    motor_mA:    { min: -5, max: 2000 }, 
    RPM:         { min: 0, max: 500000 } 
};

// Noise floor for 4-20mA signals (applied to the RAW mA input).
const noiseFloor_mA = 0.25;

// Measurement name for InfluxDB
const influxMeasurement = 'pico_measurements';

// --- End Configuration Section ---

// --- Helper Functions ---

// Scales a RAW mA value to engineering units using config
function scale_mA_Input(rawValue_mA, rangeMin, rangeMax, calibration) {
    let value_mA = rawValue_mA;
    if (value_mA < noiseFloor_mA) {
        value_mA = 0; 
    }
    const percent = (value_mA - 4) / 16;
    const clampedPercent = Math.max(0, Math.min(1, percent));
    let scaledValue = rangeMin + clampedPercent * (rangeMax - rangeMin);
    if (calibration) {
        scaledValue = scaledValue * calibration.slope + calibration.offset;
    }
    return scaledValue;
}

// Validates, scales (based on sensorType config), and checks range
function validateAndScale(rawValue, finalFieldName, deviceId) {
    if (typeof rawValue !== 'number' || isNaN(rawValue) || !isFinite(rawValue)) {
        node.warn(`Invalid raw value for ${finalFieldName} from ${deviceId}: ${rawValue}`);
        return null;
    }

    const deviceScalingConfig = scalingFactors[deviceId] || {};
    const sensorConfig = deviceScalingConfig[finalFieldName]; // Config uses FINAL name

    if (!sensorConfig) {
        node.warn(`No scaling config found for ${finalFieldName} on ${deviceId}`);
        return rawValue; 
    }

    let scaledValue = rawValue;

    // Apply scaling based on sensor type defined in config
    if (sensorConfig.sensorType === "mA_INPUT") {
        scaledValue = scale_mA_Input(rawValue, sensorConfig.rangeMin, sensorConfig.rangeMax, sensorConfig.calibration);
    } else if (sensorConfig.sensorType === "INA226" || sensorConfig.sensorType === "PULSE") {
        // Apply multiplier and offset if defined
        if (typeof sensorConfig.offset === 'number') {
            // NOTE: For INA226/PULSE, offset might be applied before multiplier depending on need.
            // Current logic: applies offset first, then multiplier.
             scaledValue += sensorConfig.offset;
        }
        if (typeof sensorConfig.multiplier === 'number') {
             scaledValue *= sensorConfig.multiplier;
        }
        // Apply calibration (y = mx + b) if provided - typically after basic scaling
        if (sensorConfig.calibration) {
            scaledValue = scaledValue * sensorConfig.calibration.slope + sensorConfig.calibration.offset;
        }
    } // Add other sensor types here if needed

    // Final range validation *after* all scaling and calibration
    const range = validRanges[finalFieldName]; // Validation uses FINAL name
    if (range && (scaledValue < range.min || scaledValue > range.max)) {
        // node.warn(`Scaled value for ${finalFieldName} from ${deviceId} is out of range: ${scaledValue} [${range.min}, ${range.max}]`);
        return null; 
    }

    return scaledValue;
}

// --- Main Function Logic ---

// Input data from Buffer Parser (e.g., { Temperature_mA: 12.5, RPM_raw: 3000, ... })
const data = msg.payload; 

// Try to get reactor number from payload, default to msg.topic or '1'
const reactorNum = data.reactor_number || msg.topic || '1'; 
const deviceId = `${deviceIdPrefix}${reactorNum}`; // Construct device ID (e.g., pico_1)

const timestamp = Date.now();

const influxData = {
    measurement: influxMeasurement,
    tags: {
        device: deviceId
    },
    timestamp: timestamp,
    fields: {}
};

// Define the FINAL field names we expect to process and output
const fieldsToProcess = ["Temperature", "pH", "ORP", "motor_mA", "RPM"];

// Map FINAL names to their corresponding RAW input names from the parser
const inputNameMapping = {
    "Temperature": "Temperature_mA",
    "pH": "pH_mA",
    "ORP": "ORP_mA",
    "RPM": "RPM_raw",         // <-- Added mapping for RPM
    "motor_mA": "motor_mA"     // motor_mA doesn't change name
};

for (const finalField of fieldsToProcess) {
    // Get the corresponding input field name from the parser output
    const inputFieldName = inputNameMapping[finalField];

    // Check if the expected input field exists in the data
    if (data.hasOwnProperty(inputFieldName)) {
        const rawValue = data[inputFieldName];
        // Validate and scale the raw value using the FINAL field name for config lookup
        const scaledValue = validateAndScale(rawValue, finalField, deviceId);

        if (scaledValue !== null) {
            // Add the scaled value to InfluxDB fields using the FINAL field name
            influxData.fields[finalField] = scaledValue;
        }
    } else {
        // node.warn(`Input field '${inputFieldName}' not found in payload for ${deviceId}`);
    }
}


if (Object.keys(influxData.fields).length > 0) {
    if (data.hasOwnProperty('reactor_number')) {
         influxData.fields.reactor_number = data.reactor_number;
    }
    msg.payload = [influxData]; 
    return msg;
} else {
    node.warn(`No valid fields to send for ${deviceId}`);
    return null; 
}

// Configuration
const REBOOT_DELAY_MS = 10 * 60 * 1000; // 10 minutes
const REBOOT_COMMAND = "sudo /sbin/reboot";
const FLOW_VAR_REBOOT_COUNT = "rebootCount_modbus";

let timerId = context.get("watchdogTimerId");
let rebootCount = flow.get(FLOW_VAR_REBOOT_COUNT) || 0;

// msg.error is set by modbus-flex-getter on its second output for errors.
// If msg comes from first output (success), msg.error will not be present or be falsy.
let isError = msg.hasOwnProperty('error') && msg.error !== null;

if (isError) {
    // Error detected
    if (!timerId) { // Start timer only if not already running
        node.status({ fill: "red", shape: "dot", text: `Error. Timer (10m) started. Reboots: ${rebootCount}` });

        // Store the first error message that triggers the timer
        context.set("triggeringErrorMsg", msg);

        timerId = setTimeout(() => {
            let currentRebootCount = flow.get(FLOW_VAR_REBOOT_COUNT) || 0; // Get latest count
            currentRebootCount++;
            flow.set(FLOW_VAR_REBOOT_COUNT, currentRebootCount);

            let originalErrorMsg = context.get("triggeringErrorMsg") || {payload: "Unknown error (context cleared)"}; // Get the stored error

            node.status({ fill: "red", shape: "ring", text: `Rebooting! Total: ${currentRebootCount}` });

            node.send([
                null, 
                { 
                    payload: REBOOT_COMMAND, 
                    rebootCount: currentRebootCount,
                    triggeringError: originalErrorMsg // Send the error that caused the reboot
                }
            ]);
            context.set("watchdogTimerId", null); // Clear timerId after firing
            context.set("triggeringErrorMsg", null); // Clear stored error
        }, REBOOT_DELAY_MS);
        context.set("watchdogTimerId", timerId);
    } else {
        // Timer already running, error persists
         node.status({ fill: "red", shape: "dot", text: `Error ongoing. Timer active. Reboots: ${rebootCount}` });
    }
} else {
    // Success
    if (timerId) {
        clearTimeout(timerId);
        context.set("watchdogTimerId", null);
        context.set("triggeringErrorMsg", null); // Clear stored error on success
        node.status({ fill: "green", shape: "dot", text: `Success. Timer cleared. Reboots: ${rebootCount}` });
    } else {
        node.status({ fill: "green", shape: "dot", text: `Success. Healthy. Reboots: ${rebootCount}` });
    }
}

// Always pass through the original incoming message (success or error) on output 1
// The timer, when it fires, sends its own message on output 2.
return [msg, null];

