const FLOW_VAR_REBOOT_COUNT = "rebootCount_modbus";
let rebootCount = flow.get(FLOW_VAR_REBOOT_COUNT) || 0;
flow.set(FLOW_VAR_REBOOT_COUNT, rebootCount); // Ensure it's initialized in flow context
node.status({fill:"blue", shape:"ring", text: "Watchdog ready. Reboots: " + rebootCount});

// Clear any orphaned timer from a previous unclean shutdown/deploy
let oldTimerId = context.get("watchdogTimerId");
if (oldTimerId) {
    clearTimeout(oldTimerId);
    context.set("watchdogTimerId", null);
    node.warn("Cleared orphaned watchdog timer on initialize.");
}
context.set("triggeringErrorMsg", null);

